import React, { useState } from "react";
const ChatWindow = ({ report }) => {
  const [messages, setMessages] = useState([
    {
      text: `Hello ${report.reporter.split(" ")[0]}, we have received your report and our team is reviewing the location.`,
      admin: true,
      time: "09:58",
    },
    {
      text: "Thank you. I can share more details if needed.",
      admin: false,
      time: "10:04",
    },
  ]);
  const [draft, setDraft] = useState("");
  const send = (event) => {
    event.preventDefault();
    if (!draft.trim()) return;
    setMessages((current) => [
      ...current,
      {
        text: draft.trim(),
        admin: true,
        time: new Date().toLocaleTimeString([], {
          hour: "2-digit",
          minute: "2-digit",
        }),
      },
    ]);
    setDraft("");
  };
  return (
    <section className="flex h-[min(590px,calc(100vh-245px))] min-h-[400px] flex-col overflow-hidden rounded-xl border border-gray-100 bg-white">
      <div className="flex items-center gap-2.5 border-b border-gray-100 p-4">
        <span className="grid h-9 w-9 place-items-center rounded-full bg-[#e5e8d9] text-xs font-bold text-[#526c46]">
          {report.reporter
            .split(" ")
            .map((part) => part[0])
            .join("")}
        </span>
        <div>
          <b className="block text-[11px]">{report.reporter}</b>
          <small className="mt-0.5 block text-[9px] text-gray-500">Citizen · Case {report.id}</small>
        </div>
        <span className="ml-auto text-[9px] text-green-700">
          <i className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-green-500" /> Case open
        </span>
      </div>
      <div className="flex-1 overflow-y-auto bg-gray-50/70 p-4">
        <div className="my-1 mb-5 text-center text-[8px] tracking-widest text-gray-400">TODAY</div>
        {messages.map((item, index) => (
          <div
            className={`mb-3 flex ${item.admin ? "justify-end" : "justify-start"}`}
            key={`${item.time}-${index}`}
          >
            <div className={`max-w-[75%] rounded-lg border px-3 py-2.5 ${item.admin ? "rounded-tr-none border-[#e0ece4] bg-[#e8f1eb]" : "rounded-tl-none border-gray-100 bg-white"}`}>
              <p className="mb-2 text-[10px] leading-relaxed">{item.text}</p>
              <small className="text-[8px] text-gray-500">
                {item.time}
                {item.admin ? " · You" : ""}
              </small>
            </div>
          </div>
        ))}
      </div>
      <form className="flex gap-2 border-t border-gray-100 p-3" onSubmit={send}>
        <input
          className="h-9 flex-1 rounded-md border border-gray-200 px-3 text-[10px] outline-green-600"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="Write a message to the citizen…"
        />
        <button className="rounded-lg bg-[#185835] px-4 text-[11px] font-semibold text-white hover:bg-[#12472a]" type="submit">
          Send <span>➤</span>
        </button>
      </form>
    </section>
  );
};
export default ChatWindow;
